import React, { useState } from "react";
import "./SearchResultsList.css";
import { SearchResult } from "./SearchResult";

export const SearchResultsList = ({ results }) => {
    return (
      <div className="results-list">
        <h2 className="results-heading"></h2>
        {results.map((result, idx) => (
          <div className="result-card" key={result.product_item_name || idx}>
            <h3 className="product-item-name">{result.product_item_name}</h3>
            <p className="product-description">
            <span className="description-label">Item Description:</span> {result.product_description}
            </p>
            <p className="business-name">
            <span className="description-label">Business Name:</span> {result.name}
            </p>
            <p className="price">{result.price}</p>
            {/* Optional: render SearchResult component if still needed */}
            {/* <SearchResult result={result} /> */}
          </div>
        ))}
      </div>
    );
  };
